<?php defined('ABSPATH')||exit;$id=get_the_ID();$terms=get_the_terms($id,'bakery_product_category');$price=function_exists('morgenbrot_product_price')?morgenbrot_product_price($id):array('regular'=>(float)morgenbrot_meta($id,'price'),'sale'=>0,'current'=>(float)morgenbrot_meta($id,'price'));$status=morgenbrot_meta($id,'availability_status')?:'in_stock';?>
<article <?php post_class('card product-card');?>><a class="card-media" href="<?php the_permalink();?>" aria-label="<?php echo esc_attr(get_the_title().' ansehen');?>"><?php if(has_post_thumbnail())the_post_thumbnail('medium_large',['alt'=>get_the_title()]);else morgenbrot_placeholder('bread');?></a><div class="card-body"><div class="card-kicker"><?php echo esc_html($terms&&!is_wp_error($terms)?$terms[0]->name:'Backware');?></div><h3><a href="<?php the_permalink();?>"><?php the_title();?></a></h3><p class="sku">SKU <?php echo esc_html(morgenbrot_meta($id,'sku')?:'—');?></p><p><?php echo esc_html(get_the_excerpt());?></p><div class="availability <?php echo esc_attr($status);?>"><?php echo esc_html(function_exists('morgenbrot_availability_label')?morgenbrot_availability_label($id):'Verfügbar');?></div><div class="card-footer"><span class="product-price"><?php if($price['sale']):?><del><?php echo esc_html(morgenbrot_format_price($price['regular']));?></del> <strong><?php echo esc_html(morgenbrot_format_price($price['sale']));?></strong><?php else:?><strong><?php echo esc_html(function_exists('morgenbrot_format_price')?morgenbrot_format_price($price['regular']):$price['regular'].' €');?></strong><?php endif;?></span><span><?php echo esc_html(morgenbrot_meta($id,'price_unit')?:morgenbrot_meta($id,'weight'));?></span></div><div class="card-actions"><a class="text-link" href="<?php the_permalink();?>">Details</a><?php if('out_of_stock'!==$status):?><a class="button small" href="<?php echo esc_url(add_query_arg(array('product'=>$id,'qty'=>1),home_url('/vorbestellen/')));?>">Zur Vorbestellung</a><?php endif;?></div></div></article>
